func (q *Queries) LockArenaCorrectionSeriesAttempts(ctx context.Context, arg LockArenaCorrectionSeriesAttemptsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, lockArenaCorrectionSeriesAttempts, arg.SeriesID, arg.TournamentID, arg.RosterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

